const body = $input.all()[0].json.body;

const now = new Date().toISOString().replace('T', ' ').substring(0, 19) + ' UTC';

const priorityEmoji = {
  Critical: '🔴',
  High:     '🟠',
  Medium:   '🟡',
  Low:      '🟢',
}[body.priority] ?? '⚪';

const subject = `[NDT Feedback] ${body.type} | ${priorityEmoji} ${body.priority}`;

const htmlBody = `
<html><body style="font-family:sans-serif;color:#1a1a1a;max-width:700px;">
  <h2 style="color:#2563eb;border-bottom:2px solid #e5e7eb;padding-bottom:8px;">NDT Portal Feedback</h2>
  <table cellpadding="6" cellspacing="0" style="border-collapse:collapse;width:100%;margin-bottom:16px;">
    <tr style="background:#f9fafb;">
      <td style="font-weight:bold;width:140px;border:1px solid #e5e7eb;">Type</td>
      <td style="border:1px solid #e5e7eb;">${body.type}</td>
    </tr>
    <tr>
      <td style="font-weight:bold;border:1px solid #e5e7eb;">Priority</td>
      <td style="border:1px solid #e5e7eb;">${priorityEmoji} ${body.priority}</td>
    </tr>
    <tr style="background:#f9fafb;">
      <td style="font-weight:bold;border:1px solid #e5e7eb;">Submitted by</td>
      <td style="border:1px solid #e5e7eb;">${body.user_name} &lt;${body.user_email}&gt;</td>
    </tr>
    <tr>
      <td style="font-weight:bold;border:1px solid #e5e7eb;">Page</td>
      <td style="border:1px solid #e5e7eb;"><a href="${body.page_url}">${body.page_url}</a></td>
    </tr>
    <tr style="background:#f9fafb;">
      <td style="font-weight:bold;border:1px solid #e5e7eb;">Submitted at</td>
      <td style="border:1px solid #e5e7eb;">${now}</td>
    </tr>
  </table>
  <h3 style="margin-bottom:4px;">Description</h3>
  <div style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:6px;padding:12px;white-space:pre-wrap;">${body.description}</div>
  ${body.screenshot_b64 ? '<p style="margin-top:16px;color:#6b7280;font-size:13px;">📎 Screenshot attached (feedback-screenshot.png)</p>' : ''}
</body></html>
`;

const hasScreenshot = !!(body.screenshot_b64);
let screenshotBase64 = '';
if (hasScreenshot) {
  screenshotBase64 = body.screenshot_b64.replace(/^data:image\/\w+;base64,/, '');
}

return [{
  json: {
    subject,
    htmlBody,
    hasScreenshot,
    screenshotBase64,
    toEmail: 'mrt@mrt.cc',
  }
}];

const item = $input.all()[0];
const base64 = item.json.screenshotBase64;
const buffer = Buffer.from(base64, 'base64');

return [{
  json: item.json,
  binary: {
    screenshot: await this.helpers.prepareBinaryData(
      buffer,
      'feedback-screenshot.png',
      'image/png'
    )
  }
}];
